pragma solidity >=0.8.0;

contract CryptoEncodeLength {
    function packedLen(uint8 a, uint16 b, uint64 c, uint256 d) public pure returns (uint256) {
        return abi.encodePacked(a, b, c, d).length;
    }
    function encodedLen(uint8 a, uint16 b, uint64 c, uint256 d) public pure returns (uint256) {
        return abi.encode(a, b, c, d).length;
    }
    function packedLenStr(uint8 a, string memory b, bytes memory c) public pure returns (uint256) {
        return abi.encodePacked(a, b, c).length;
    }
    function encodedLenStr(uint8 a, string memory b, bytes memory c) public pure returns (uint256) {
        return abi.encode(a, b, c).length;
    }
}
